import React, { useEffect, useRef, useState } from 'react';
import { dispatchAppToast, getActiveCompanyCode, getAuthUser, FormSkeleton, useMinLoadingTime, getCompanyBranding, Tabs } from '@linm-soft-org/linm-web-common-components';
import { VoucherFormToolbar } from '../../../../../components/voucher';
import { VoucherFormStatusGroup } from '../../../../../components/voucher/VoucherFormStatusGroup';
import { useTopbarAutoHideOnScroll, useVoucherFormShellHeight, useFormEmbedSlideout } from '../../../../../components/form';
import { formatProcessingLevelFromOptions } from '../../../../../utils/voucherProcessingLevelOptions';
import { resolveVoucherViewModeHint } from '../../../../../utils/voucherProcessingLevelDisplay';
import type { CashVoucherKind } from '../../../../../components/kt/CashVoucherList';
import { useCashVoucherFormController } from '../hooks/useCashVoucherFormController';
import { CashVoucherValidationBanner } from './CashVoucherValidationBanner';
import { CashVoucherHeaderSection } from './CashVoucherHeaderSection';
import { CashVoucherLinesSection } from './CashVoucherLinesSection';
import { CashVoucherFooterSection } from './CashVoucherFooterSection';
import { CashVoucherFormModals } from './CashVoucherFormModals';
import { CompanyAllocationViewSection } from '../../../../../components/kt/CompanyAllocationViewSection';
import styles from '../../../../../styles/documentForm.module.css';

export const CashVoucherFormParent: React.FC<{ kind: CashVoucherKind }> = ({ kind }) => {
  const vm = useCashVoucherFormController(kind);
  const embedSlideout = useFormEmbedSlideout();
  const shellRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const dispatch = vm.dispatch;
  useVoucherFormShellHeight(shellRef, !embedSlideout);
  useTopbarAutoHideOnScroll(scrollRef, !embedSlideout);

  // Must be before early returns (Rules of Hooks)
  const tabLabel = vm.voucherTitle || vm.formTitle || (vm.isNew ? vm.labels?.createTitle : vm.labels?.title);
  const showFormSkeleton = useMinLoadingTime(vm.initLoading || vm.showInitialLoading, 300);
  const [bodyTab, setBodyTab] = useState<'chung-tu' | 'phan-bo'>('chung-tu');
  const showAllocTab = !vm.isViewMode || (vm.companyAllocations?.length ?? 0) > 0;
  useEffect(() => {
    if (vm.allocationMismatch && showAllocTab) setBodyTab('phan-bo');
  }, [vm.allocationMismatch, showAllocTab]);
  useEffect(() => {
    if (!showAllocTab && bodyTab === 'phan-bo') setBodyTab('chung-tu');
  }, [showAllocTab, bodyTab]);

  useEffect(() => {
    if (vm.voucherNumber && typeof window.__LINM_UPDATE_TAB_TITLE__ === 'function') {
      window.__LINM_UPDATE_TAB_TITLE__(`${tabLabel} — ${vm.voucherNumber}`);
    }
  }, [vm.voucherNumber, tabLabel]);
  useEffect(() => {
    window.__LINM_IS_CURRENT_TAB_DIRTY__ = vm.isDirty;
    return () => { window.__LINM_IS_CURRENT_TAB_DIRTY__ = false; };
  }, [vm.isDirty]);

  if (vm.initError) {
    return (
      <div className={styles.pageVoucher} data-testid={vm.tid('init-error')}>
        <div className={styles.formErrorMessage}>
          <p className={styles.formErrorTitle}>Không thể tải dữ liệu form</p>
          <p className={styles.formErrorDetail}>{vm.initError}</p>
        </div>
      </div>
    );
  }

  if (showFormSkeleton) {
    return <FormSkeleton headerRows={2} lineRows={3} data-testid={vm.tid('form-skeleton')} />;
  }

  const {
    cfg,
    labels,
    isNew,
    voucherNumber,
    voucherCompanyCode,
    toolbarMode,
    isViewMode,
    status,
    saving,
    tid,
    hasSearchNav,
    searchNavIndex,
    searchResultIds,
    navigateToSearchId,
    handleBack,
    setShowApproveModal,
    handleCopy,
    setShowPrintModal,
    setShowHistoryModal,
    setShowSearchSlideout,
    handleNew,
    handleEdit,
    handleSave,
    handleCancel,
    setShowDeleteModal,
    saveLabel,
    refreshing,
    validationErrors,
    bannerClosed,
    bannerExpanded,
    setBannerExpanded,
    setBannerClosed,
    validationBannerId,
    processingLevel,
    setProcessingLevel,
    processingOpts,
    selectDisabled,
    totalAmount,
    viewSectionClass,
    toolbarDisabledReasons,
    canViewLedger,
    canViewLinkedInvoices,
    showEditDelete,
    canApproveToolbar,
    showApproveToolbar,
    canCopyToolbar,
    canPrintToolbar,
    canDeleteToolbar,
    canSaveToolbar,
    copySourceVoucherCode,
    showCompanyAllocateBtn,
    canCompanyAllocate,
    canOpenCompanyAllocate,
    companyAllocateDisabledReason,
    openCompanyAllocate,
    companyAllocations,
  } = vm;

  const documentHistoryType = 'documentHistoryType' in cfg ? cfg.documentHistoryType : undefined;

  const processingLevelLabel = formatProcessingLevelFromOptions(processingLevel, processingOpts);

  // ── Cross-company badge ──
  const activeCompanyCode = getActiveCompanyCode();
  const authUser = getAuthUser();
  const userHasMultipleCompanies = authUser?.canViewAllCompanies
    || authUser?.role === 'admin'
    || (authUser?.allowedCompanyCodes?.length ?? 0) > 0;
  const showBadge = userHasMultipleCompanies && !!(voucherCompanyCode || activeCompanyCode);
  const badgeCompanyCode = voucherCompanyCode || activeCompanyCode || '';
  const companyBranding = getCompanyBranding();
  const badgeLabel = companyBranding?.code === badgeCompanyCode && companyBranding?.shortName
    ? companyBranding.shortName
    : badgeCompanyCode;

  return (
    <div
      ref={shellRef}
      className={[
        styles.pageVoucher,
        embedSlideout ? styles.pageVoucherSlideoutEmbed : '',
        refreshing ? styles.pageRefreshing : '',
      ].filter(Boolean).join(' ')}
      data-voucher-form-shell
      data-form-embed-slideout={embedSlideout || undefined}
      data-testid={tid('form')}
      aria-busy={refreshing}
    >
      {!embedSlideout && (
      <div className={styles.pageFormHeader}>
        <div className={styles.stickyTop}>
          <VoucherFormToolbar
          testIdPrefix={cfg.testIdPrefix}
          title={isNew
            ? (vm.formTitle ? `Tạo ${vm.formTitle}` : labels.createTitle)
            : `${vm.voucherTitle || vm.formTitle || labels.title} — ${voucherNumber || '...'}`}
          processingLevelBadge={
            !isNew ? <VoucherFormStatusGroup processingLevelLabel={processingLevelLabel} /> : undefined
          }
          companyBadge={showBadge ? (
            <span
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 4,
                padding: '2px 8px',
                borderRadius: 4,
                fontSize: 12,
                fontWeight: 600,
                background: '#e0f2fe',
                color: '#0369a1',
                border: '1px solid #7dd3fc',
                whiteSpace: 'nowrap',
              }}
              title={`Đơn vị hoạch toán: ${badgeCompanyCode}`}
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ marginRight: 2 }}>
                <rect x="2" y="3" width="20" height="14" rx="2" ry="2" />
                <line x1="8" y1="21" x2="16" y2="21" />
                <line x1="12" y1="17" x2="12" y2="21" />
              </svg>
              {badgeLabel}
            </span>
          ) : undefined}
          formMode={toolbarMode}
          viewModeHint={resolveVoucherViewModeHint({
            formMode: toolbarMode,
            isNew,
            status,
            processingLevel,
            canEditWhenView: showEditDelete,
          })}
          copySourceVoucherCode={copySourceVoucherCode}
          showApproveButton={showApproveToolbar}
          canApprove={canApproveToolbar}
          showPostButton={false}
          canPost={false}
          canCopy={canCopyToolbar}
          canPrint={canPrintToolbar}
          canHistory={!isNew && !!documentHistoryType}
          showEditButton={showEditDelete}
          showDeleteButton={canDeleteToolbar}
          showNewButton={vm.formPermissions?.canCreate ?? false}
          canEdit={showEditDelete}
          canDelete={canDeleteToolbar}
          canSave={canSaveToolbar}
          disabledReasons={toolbarDisabledReasons}
          saving={saving}
          searchNav={hasSearchNav ? {
            index: searchNavIndex,
            total: searchResultIds.length,
            onFirst: () => navigateToSearchId(searchResultIds[0]),
            onPrev: () => navigateToSearchId(searchResultIds[searchNavIndex - 1]),
            onNext: () => navigateToSearchId(searchResultIds[searchNavIndex + 1]),
            onEnd: () => navigateToSearchId(searchResultIds[searchResultIds.length - 1]),
          } : undefined}
          onBack={handleBack}
          onApprove={() => setShowApproveModal(true)}
          onPost={() => {}}
          canViewLedger={canViewLedger}
          onViewLedger={() => vm.setShowLedgerModal(true)}
          canViewLinkedVoucher={canViewLinkedInvoices}
          onViewLinkedVoucher={() => vm.setShowLinkedInvoicesSlideout(true)}
          viewLinkedVoucherLabel="Xem hóa đơn"
          showAllocateButton={showCompanyAllocateBtn}
          canAllocate={canOpenCompanyAllocate}
          onAllocate={() => vm.openCompanyAllocate()}
          allocateLabel="Phân bổ"
          allocateDisabledReason={companyAllocateDisabledReason}
          onCopy={handleCopy}
          onPrint={() => setShowPrintModal(true)}
          onHistory={documentHistoryType ? () => setShowHistoryModal(true) : undefined}
          onSearch={() => setShowSearchSlideout(true)}
          onNew={handleNew}
          onEdit={handleEdit}
          onSave={handleSave}
          onCancel={handleCancel}
          onDelete={() => setShowDeleteModal(true)}
          saveLabel={saveLabel}
          insetShell
        />
        </div>
      </div>
      )}

      <div ref={scrollRef} className={styles.pageFormScroll} data-testid={tid('form-scroll')}>
        <CashVoucherValidationBanner
          validationErrors={validationErrors}
          bannerClosed={bannerClosed}
          bannerExpanded={bannerExpanded}
          setBannerExpanded={setBannerExpanded}
          setBannerClosed={setBannerClosed}
          validationBannerId={validationBannerId}
          tid={tid}
        />

        {!isNew && showAllocTab && (
          <div style={{ marginBottom: 8 }} data-testid={tid('body-tabs')}>
            <Tabs
              tabs={[
                { id: 'chung-tu', label: 'Chứng từ' },
                {
                  id: 'phan-bo',
                  label: companyAllocations.length > 0
                    ? `Phân bổ (${companyAllocations.length})`
                    : 'Phân bổ',
                },
              ]}
              activeTab={bodyTab}
              onTabChange={id => setBodyTab(id as 'chung-tu' | 'phan-bo')}
              variant="underline"
              density="compact"
            />
          </div>
        )}
        {(isNew || bodyTab === 'chung-tu' || !showAllocTab) && (
          <>
            <CashVoucherHeaderSection vm={vm} />
            <CashVoucherLinesSection vm={vm} />
          </>
        )}
        {!isNew && showAllocTab && bodyTab === 'phan-bo' && (
          companyAllocations.length > 0 ? (
            <>
              {vm.allocationMismatch ? (
                <p
                  style={{ margin: '0 0 10px', padding: '8px 10px', borderRadius: 6, background: '#fef3c7', color: '#92400e', fontSize: 13 }}
                  data-testid={tid('allocation-mismatch')}
                >
                  Số tiền phiếu đã lệch phân bổ — nhập lại và xác nhận phân bổ.
                </p>
              ) : null}
              <CompanyAllocationViewSection
                lines={companyAllocations}
                testIdPrefix={cfg.testIdPrefix}
                canEdit={canCompanyAllocate}
                onOpenSlideout={() => openCompanyAllocate()}
                groupByLine
              />
            </>
          ) : (
            <div className={styles.formSection} data-testid={tid('allocation-empty')}>
              <p style={{ margin: '8px 0', fontSize: 13, color: '#64748b' }}>
                Chưa phân bổ. Mặc định <strong>full phiếu</strong> — bấm Phân bổ trên toolbar sau khi lưu.
              </p>
            </div>
          )
        )}
      </div>

      <div className={styles.pageFormFooter} data-testid={tid('form-footer')}>
        <CashVoucherFooterSection
          labels={labels}
          tid={tid}
          viewSectionClass={viewSectionClass}
          processingLevel={processingLevel}
          setProcessingLevel={setProcessingLevel}
          processingOpts={processingOpts}
          selectDisabled={selectDisabled}
          totalAmount={totalAmount}
          defaultProcessingLevel={vm.defaultProcessingLevel}
        />
      </div>

      <CashVoucherFormModals vm={vm} />
    </div>
  );
};

export default CashVoucherFormParent;
