import type {
  CashVoucherCompanyAllocationDto,
  CompanyAllocationScope,
  SaveCashVoucherCompanyAllocationDto,
} from '../../../../../services/kt/models';

const TOLERANCE = 1;

export type AllocMatchLine = {
  id: string;
  amount: number;
  rowOrderKey: number;
};

function round0(n: number): number {
  return Math.round(Number(n) || 0);
}

function allocsForLine(
  allocs: CashVoucherCompanyAllocationDto[],
  line: AllocMatchLine,
): CashVoucherCompanyAllocationDto[] {
  return allocs.filter(a => {
    const lineId = (a.cashVoucherLineId ?? '').trim();
    if (lineId && lineId === line.id) return true;
    const key = Number(a.rowOrderKey) || 0;
    return key > 0 && key === line.rowOrderKey;
  });
}

/** Common = tổng phiếu. ByLine = chỉ dòng đã phân bổ phải khớp; dòng không phân bổ bỏ qua. */
export function getCashAllocationMismatchMessage(
  scope: CompanyAllocationScope | string | null | undefined,
  allocs: CashVoucherCompanyAllocationDto[] | null | undefined,
  voucherTotal: number,
  lines: AllocMatchLine[],
): string | null {
  if (!allocs || allocs.length === 0) return null;
  const isByLine = String(scope ?? '').toLowerCase() === 'byline';

  if (!isByLine) {
    const target = round0(voucherTotal);
    const sum = allocs.reduce((s, a) => s + round0(a.amount), 0);
    if (Math.abs(sum - target) > TOLERANCE) {
      return `Tổng phân bổ (${sum.toLocaleString('vi-VN')}) phải khớp tổng phiếu (${target.toLocaleString('vi-VN')}).`;
    }
    return null;
  }

  for (const line of lines) {
    const lineTotal = round0(line.amount);
    if (lineTotal <= 0) continue;
    const lineAllocs = allocsForLine(allocs, line);
    if (lineAllocs.length === 0) continue;
    const sum = lineAllocs.reduce((s, a) => s + round0(a.amount), 0);
    if (Math.abs(sum - lineTotal) > TOLERANCE) {
      return `Dòng ${line.rowOrderKey}: tổng phân bổ (${sum.toLocaleString('vi-VN')}) phải khớp (${lineTotal.toLocaleString('vi-VN')}).`;
    }
  }
  return null;
}

export function toLocalAllocationDtos(
  payload: SaveCashVoucherCompanyAllocationDto,
  lines: AllocMatchLine[],
): CashVoucherCompanyAllocationDto[] {
  return (payload.lines ?? []).map((l, i) => {
    const lineId = (l.cashVoucherLineId ?? '').trim();
    const fromLine = lineId ? lines.find(x => x.id === lineId) : undefined;
    return {
      id: `local-${i}`,
      targetCompanyCode: l.targetCompanyCode,
      targetCompanyName: l.targetCompanyName,
      amount: l.amount,
      ratio: l.ratio,
      method: payload.method,
      sortOrder: l.sortOrder ?? i,
      cashVoucherLineId: l.cashVoucherLineId,
      isRoundingDiff: l.isRoundingDiff,
      costCode: l.costCode,
      rowOrderKey: l.rowOrderKey && l.rowOrderKey > 0
        ? l.rowOrderKey
        : (fromLine?.rowOrderKey ?? 0),
    };
  });
}

export function toSaveAllocationPayload(
  method: string,
  scope: string,
  allocs: CashVoucherCompanyAllocationDto[],
): SaveCashVoucherCompanyAllocationDto | undefined {
  if (allocs.length === 0) return undefined;
  return {
    method,
    scope,
    lines: allocs.map((a, i) => ({
      targetCompanyCode: a.targetCompanyCode,
      targetCompanyName: a.targetCompanyName ?? undefined,
      amount: a.amount,
      ratio: a.ratio,
      sortOrder: a.sortOrder ?? i,
      cashVoucherLineId: a.cashVoucherLineId,
      isRoundingDiff: a.isRoundingDiff,
      costCode: a.costCode,
      rowOrderKey: a.rowOrderKey,
    })),
  };
}
