import type { CashVoucherShellProfile } from '../features/kt/cash-voucher/shared/config/cashVoucherShellProfiles';
import type { PostingReasonInitItem } from '../services/voucherInit/endpoint';
import type { PostingReasonRuleDto } from '../services/kt/models';

/**
 * Map shell → posting reason voucher type (slug).
 *
 * PostingReasonRule stores AllowedVoucherTypeCodes as slugs ('phieu-thu', 'phieu-chi').
 * The shell now uses short codes ('PT', 'PC', 'BC', 'BN', 'UNC') for VoucherRegistry lookup,
 * so we resolve back to slugs here.
 */
export function resolvePostingReasonVoucherTypeCode(shell: Pick<CashVoucherShellProfile, 'voucherRegistryCode'>): string {
  switch (shell.voucherRegistryCode) {
    case 'BC':    // giay-bao-co → phieu-thu
      return 'phieu-thu';
    case 'BN':    // giay-bao-no → phieu-chi
    case 'UNC':   // uy-nhiem-chi → phieu-chi
      return 'phieu-chi';
    case 'PT':    // phieu-thu → identity
      return 'phieu-thu';
    case 'PC':    // phieu-chi → identity
      return 'phieu-chi';
    default:
      return shell.voucherRegistryCode;
  }
}

export function mapPostingReasonRuleToInitItem(rule: PostingReasonRuleDto): PostingReasonInitItem {
  return {
    code: rule.code,
    name: rule.name,
    debitAccountCode: rule.debitAccountCode,
    creditAccountCode: rule.creditAccountCode,
    erpDebitAccountCode: rule.erpDebitAccountCode,
    erpCreditAccountCode: rule.erpCreditAccountCode,
    allowEditPostingAccounts: rule.allowEditPostingAccounts ?? false,
    suggestOnly: rule.suggestOnly ?? false,
    expenseItemCode: rule.expenseItemCode ?? null,
  };
}

/** Parse `ExpenseItemCode` CSV (BE PostingReasonVoucherAccess.Parse parity). */
export function parseExpenseItemCodes(raw?: string | null): string[] {
  if (!raw?.trim()) return [];
  return raw
    .split(/[,;|\n\r]/)
    .map(s => s.trim())
    .filter(Boolean);
}

/**
 * Index ĐK theo mã CP — first-wins (parity BE BankStatementExpenseGrepMapper.BuildRules).
 */
export function buildPostingReasonByExpenseCode(
  reasons: PostingReasonInitItem[],
): Map<string, PostingReasonInitItem> {
  const map = new Map<string, PostingReasonInitItem>();
  for (const r of reasons) {
    for (const code of parseExpenseItemCodes(r.expenseItemCode)) {
      const key = code.toUpperCase();
      if (!map.has(key)) map.set(key, r);
    }
  }
  return map;
}
